import { guideLesson } from './define.ts';
import type { Lesson } from './types.ts';
const G = (slug: string, title: string, prerequisites: string[], objectives: string[], sections: Lesson['sections'], question: string, options: string[], answer: number, explanation: string, optional = false): Lesson => guideLesson('gold', slug, { title, description: objectives.join(' · '), minutes: 35, prerequisites, objectives, sections, quiz: { question, options, answer, explanation }, optional });
export const goldLessons: Lesson[] = [
G('divisibility','Divisibilidad, primos y máximo común divisor',['usaco-bronze-time-comp'],['Descomponer números en factores primos','Justificar Euclides y una criba'],[
{title:"Repartir sin que sobre nada",body:"Tienes 42 fichas de un color y 30 de otro, y quieres armar paquetes del mismo tamaño sin mezclar colores ni dejar fichas sueltas. Puedes hacer paquetes de seis. El máximo común divisor, mcd, describe el mayor tamaño permitido. Un número primo tiene exactamente dos divisores positivos.\n\nCada entero mayor que uno posee una factorización prima única salvo el orden; esta propiedad convierte preguntas sobre divisores en preguntas sobre exponentes. Antes de programar, distingue encontrar un divisor, factorizar un número y listar todos los primos hasta un límite."},
{title:"Qué comparten 84 y 30",body:"Descompón 84=2²·3·7 y 30=2·3·5. Para el máximo común divisor toma los exponentes menores de cada primo: queda 2·3=6. Los mayores producen mcm = 420. También mcm(a,b) = a / mcd(a,b) · b para enteros positivos. Euclides da mcd(84,30) = mcd(30,24) = mcd(24,6) = 6.\n\nEl paso conserva los divisores comunes porque cualquier divisor de a y b divide a − qb, y el argumento funciona también en sentido contrario."},
{title:"Dos cálculos que conviene separar",body:"Euclides cambia (a,b) por (b,a%b) y repite hasta que b vale cero; el otro número es el máximo común divisor. Para muchos primos, la criba comienza suponiendo primos los enteros desde dos y marca múltiplos. Basta iniciar cada marcado en p²: los múltiplos menores ya tenían un factor primo menor.\n\nSi solo factorizas x, prueba divisores mientras d ≤ x/d y divide repetidamente; al terminar, un resto mayor que uno es primo.",code:'#include <iostream>\n#include <numeric>\nusing namespace std;\nint main(){ long long a,b; cin>>a>>b; cout<<gcd(a,b)<<"\\n"; }'},
{title:"Cuánto trabajo necesita cada método",body:"Euclides hace O(log min(a,b)) operaciones; probar divisores hasta la raíz cuesta O(√x). Para encontrar todos los primos hasta N, la criba cuesta O(N log log N) y guarda O(N) datos. Estas cotas cuentan operaciones aritméticas sobre enteros del tamaño admitido. No marques uno como primo ni calcules a*b antes de dividir si puede desbordar.\n\nPractica contando los divisores de 360: para 2³·3²·5, cada exponente se elige independientemente, así que hay 4·3·2 = 24 posibilidades."}
],'¿Cuál es el mcd de 48 y 18?',['3','6','12','18'],1,'48 = 2·18 + 12 y 18 = 12 + 6; el último resto no nulo es 6.'),
G('modular','Aritmética modular y potencias rápidas',['usaco-gold-divisibility'],['Operar residuos sin perder información útil','Reconocer cuándo existe un inverso'],[
{title:"El residuo de una vuelta",body:"En un reloj de doce horas, avanzar doce posiciones te deja donde empezaste. Escribimos a ≡ b (mod m) cuando m divide a − b. Podemos sustituir números por sus residuos en sumas, restas y productos. Esto permite contar resultados enormes sin almacenarlos completos cuando el enunciado pide únicamente su residuo. El módulo debe permanecer fijo durante el cálculo; cambiarlo a mitad de una recurrencia destruye la interpretación."},
{title:"Calcular una potencia con pocos productos",body:"Para calcular 3¹³ módulo 7, separa 13 como 8+4+1 y aprovecha potencias que ya calculaste. Los cuadrados sucesivos dan 3, 2, 4 y 2 como residuos de 3¹, 3², 3⁴ y 3⁸. Multiplicamos los seleccionados: 2·4·3 ≡ 3. Durante todo el cálculo, resultado · base^exponente debe conservar el residuo de la potencia original. En cada vuelta consumimos un bit del exponente y elevamos la base al cuadrado.",code:'#include <iostream>\nusing namespace std;\nint main(){ long long a,e,m; cin>>a>>e>>m; if(m<=0 || m>1000000007LL || e<0) return 0; a=(a%m+m)%m; long long r=1%m; while(e){ if(e&1) r=r*a%m; a=a*a%m; e>>=1; } cout<<r<<"\\n"; }'},
{title:"Dividir necesita una comprobación",body:"Dividir entre a módulo m requiere encontrar un número b tal que a·b deje residuo 1. El inverso de a existe cuando mcd(a,m)=1. Por ejemplo, módulo 7 el inverso de 3 es 5 porque 3·5 ≡ 1. Si p es primo y a no es múltiplo de p, el pequeño teorema de Fermat permite calcularlo como a^(p−2).\n\nMódulo 8, el número 2 carece de inverso; ninguna potencia remedia esa ausencia."},
{title:"Límites y casos que puedes probar",body:"La potencia rápida necesita O(log e) tiempo y O(1) memoria: cada vuelta reduce a la mitad el exponente pendiente. El programa limita m para que multiplicar dos residuos quepa en long long; para módulos mayores necesitas multiplicación segura. En C++, un resto negativo puede ser negativo: normaliza con (x%m+m)%m. Prueba exponente cero, módulo uno y base negativa.\n\nComo ejercicio, demuestra que 10⁹ módulo 9 es uno y explica por qué dividir entre tres módulo nueve no está definido de manera única."}
],'¿Qué número es inverso de 4 módulo 7?',['2','3','4','No existe'],0,'4·2 = 8 ≡ 1 (mod 7), así que multiplicar por 2 deshace la multiplicación por 4.'),
G('combo','Combinatoria: contar sin enumerar',['usaco-gold-modular'],['Distinguir elecciones ordenadas y conjuntos','Calcular coeficientes binomiales'],[
{title:"Elegir un equipo o elegir cargos",body:"De cinco estudiantes puedes elegir un equipo de dos o asignar dos cargos distintos: son preguntas diferentes. Elegir capitán y suplente entre cinco estudiantes tiene 5·4 resultados: los cargos distinguen el orden. Elegir dos representantes sin cargos tiene diez, porque cada pareja se había contado dos veces.\n\nLa regla del producto sirve para decisiones sucesivas; la regla de la suma sirve para casos incompatibles que cubren todas las posibilidades."},
{title:"Por qué dividimos al contar conjuntos",body:"C(n,k) cuenta conjuntos de k elementos elegidos entre n: cambiar el orden de una misma selección no crea otra. La fórmula n!/(k!(n−k)!) elimina las permutaciones internas que no distinguen conjuntos. Para elegir tres de siete personas, 7·6·5/(3·2·1)=35. Otra explicación separa los equipos según incluyan a una persona elegida: C(n,k)=C(n−1,k−1)+C(n−1,k), con C(n,0)=C(n,n)=1. Esta recurrencia forma el triángulo de Pascal y no exige división."},
{title:"Preparar las combinaciones pequeñas",body:"Si n es pequeño y necesitas varias combinaciones, llena las filas del triángulo de Pascal con las respuestas anteriores. Con un módulo primo p y n<p puedes precalcular factoriales e inversos factoriales en O(n + log p), y responder cada consulta en O(1). La condición n<p importa: n! sería cero módulo p cuando n≥p y ya no tendría inverso.\n\nEl programa usa Pascal exacto para n≤60 y comprueba las fronteras.",code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main(){ int n,k; cin>>n>>k; if(n<0||n>60||k<0||k>n) return 0; vector<long long> c(k+1); c[0]=1; for(int i=1;i<=n;i++) for(int j=min(i,k);j>=1;j--) c[j]+=c[j-1]; cout<<c[k]<<"\\n"; }'},
{title:"Conservar la fila anterior",body:"Pascal con una fila tarda O(nk) y usa O(k) memoria. Recorre k de mayor a menor para no reutilizar valores que ya cambiaste en esa misma fila. No uses factoriales en enteros comunes sin estimar su tamaño: 21! ya excede un entero con signo de 64 bits. Practica contando caminos de una esquina a otra de una cuadrícula con cuatro pasos a la derecha y dos hacia arriba.\n\nCada camino corresponde a elegir las dos posiciones verticales entre seis, por lo que hay C(6,2)=15."}
],'¿Cuántos equipos de dos se forman con seis estudiantes?',['12','15','30','36'],1,'Hay 6·5 parejas ordenadas; cada equipo aparece dos veces, así que 30/2=15.'),
G('intro-dp','Programación dinámica desde el estado',['usaco-bronze-complete-rec'],['Definir un estado con significado exacto','Construir recurrencias y casos base'],[
{title:"Guardar una respuesta para volver a usarla",body:"La programación dinámica guarda respuestas de preguntas pequeñas que se repiten. En una escalera donde puedes subir uno o dos peldaños, varias secuencias te llevan a la misma altura. Si estás en el peldaño tres, tus próximos saltos no dependen de cómo llegaste allí.\n\nEso permite reunir esas historias en un estado: la información que basta para continuar. Antes de llenar una tabla, define qué pregunta contesta cada entrada y comprueba que no hayas olvidado alguna restricción del pasado."},
{title:"Contar las formas de subir cuatro escalones",body:"Llama dp[i] a la cantidad de maneras de llegar al escalón i; para llegar al cuarto, el último salto viene del tercero o del segundo. El último salto mide uno o dos, de modo que dp[i]=dp[i−1]+dp[i−2]. Cada recorrido termina con uno de esos saltos, y nunca con ambos a la vez; por eso puedes sumar sin repetir rutas. Fijamos dp[0]=1: existe un recorrido vacío.\n\nPara alturas 0,1,2,3,4 nos queda 1,1,2,3,5. En cuatro peldaños, por ejemplo, aparecen 1111,112,121,211 y 22.\n\nUna buena recurrencia incluye explícitamente qué sucede en índices negativos."},
{title:"Llenar la tabla en un orden útil",body:"Calcula los escalones de menor a mayor para que cada suma use respuestas que ya conoces. También puedes usar recursión con memoria, siempre que marques qué estados ya calculaste. Si aparecen ciclos entre estados, esta receta no basta: debes cambiar la representación o estudiar otro algoritmo.\n\nEl programa acepta hasta 90 peldaños para mantener el resultado exacto dentro de long long; en problemas mayores podría solicitarse una respuesta modular.",code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){ int n; cin>>n; if(n<0||n>90) return 0; vector<long long> dp(n+1); dp[0]=1; for(int i=1;i<=n;i++){ dp[i]=dp[i-1]; if(i>=2) dp[i]+=dp[i-2]; } cout<<dp[n]<<"\\n"; }'},
{title:"Cambiar la pregunta que guarda la tabla",body:"En los escalones hay n estados y cada uno suma dos respuestas: el tiempo es O(n). La tabla ocupa O(n), aunque bastaría conservar las dos cantidades anteriores. No confundas contar formas con minimizar costo: al minimizar normalmente usarías infinito para estados imposibles y un mínimo entre candidatos. Como ejercicio, prohíbe el tercer peldaño y calcula las formas de llegar al quinto.\n\nDebes forzar dp[3]=0; los valores posteriores se vuelven 2 y 2, mostrando que las condiciones del estado afectan el conteo."}
],'¿Cuántas formas hay de subir cinco peldaños con saltos de uno o dos?',['5','6','8','10'],2,'dp[3]=3 y dp[4]=5; el último salto separa los recorridos y dp[5]=3+5=8.'),
G('knapsack','Mochila y elecciones con capacidad',['usaco-gold-intro-dp'],['Diseñar estados de capacidad o valor','Separar mochila 0/1 e ilimitada'],[
{title:"Qué cabe en una mochila",body:"Cada objeto tiene un peso y un valor; quieres conseguir el mayor valor sin superar la capacidad de la mochila. En la variante 0/1 puedes tomar cada objeto a lo sumo una vez. Define dp[i][w] como el mayor valor usando los primeros i objetos con peso total a lo sumo w. La decisión sobre el objeto i divide las soluciones entre no tomarlo y tomarlo si cabe.\n\nEsa separación convierte una búsqueda de subconjuntos en una tabla."},
{title:"Tres objetos y capacidad cinco",body:"Con objetos (peso,valor) iguales a (2,3), (3,4) y (4,5), una mochila de capacidad cinco puede llevar los dos primeros y obtener siete. La transición compara dp[i−1][w] con dp[i−1][w−peso_i]+valor_i. Si usamos solo una fila, debemos recorrer capacidades de W hacia peso_i: así dp[w−peso_i] aún representa los objetos anteriores. Recorrer hacia arriba permitiría usar repetidamente el mismo objeto y resolvería otro problema."},
{title:"Qué lee el programa y qué guarda",body:"El código lee n y la capacidad W, seguidos de n pares con el peso y el valor de cada objeto. Inicializar toda la fila a cero representa capacidad máxima disponible, no peso exacto. Para exigir peso exactamente W, inicia solo dp[0]=0 y los demás como imposibles.\n\nCuando los pesos son gigantes pero la suma de valores es pequeña, invierte la definición: guarda el peso mínimo necesario para obtener cada valor.",code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main(){ int n,W; cin>>n>>W; vector<long long> dp(W+1); for(int i=0;i<n;i++){ int w; long long v; cin>>w>>v; for(int c=W;c>=w;c--) dp[c]=max(dp[c],dp[c-w]+v); } cout<<dp[W]<<"\\n"; }'},
{title:"Cuándo cabe una tabla por peso",body:"El algoritmo de mochila tarda O(nW) y guarda O(W) valores si conserva una sola fila. Es seudopolinomial: W puede ser enorme respecto a la cantidad de bits que lo representan, así que revisa límites antes de elegirla. Asume pesos no negativos y capacidad representable; con objetos ilimitados de peso cero y valor positivo el óptimo no sería finito.\n\nPractica el ejemplo con capacidad seis: el objeto de peso dos junto con el de peso cuatro logra valor ocho. Explica por qué ordenar por valor/peso no garantiza una solución 0/1 óptima."}
],'Al procesar un objeto 0/1 en una sola fila, ¿cómo recorres capacidades?',['De menor a mayor','De mayor a menor','En cualquier orden'],1,'Descender evita que dp[w−peso] haya incorporado ya el mismo objeto en esa iteración.'),
G('paths-grids','Caminos y estados en cuadrículas',['usaco-gold-intro-dp'],['Contar caminos con obstáculos','Reconocer una cuadrícula como DAG'],[
{title:"Contar rutas hasta una casilla",body:"En una cuadrícula donde solo avanzas a la derecha o hacia abajo, el último paso hacia una casilla viene de arriba o de la izquierda. El orden de filas y columnas impide regresar a una celda anterior, así que las dependencias forman un grafo dirigido sin ciclos. Define dp[f][c] como la cantidad de caminos desde el origen hasta esa celda.\n\nUn obstáculo elimina todos los caminos que intentarían terminar allí, aunque existan rutas a sus vecinos."},
{title:"Una cuadrícula de tres por tres",body:"En una cuadrícula libre de 3×3 hay seis rutas desde la esquina superior izquierda hasta la inferior derecha. Si bloqueas el centro, la primera fila y primera columna siguen valiendo uno, el centro vale cero y las dos celdas junto al destino valen uno. El destino recibe 1+1=2. La fórmula es dp[f][c]=dp[f−1][c]+dp[f][c−1] para celdas libres.\n\nEl origen vale uno si está libre y cero si está bloqueado; no lo inicialices incondicionalmente."},
{title:"Reutilizar una fila de respuestas",body:"Si recorres de izquierda a derecha, dp[c] todavía guarda la respuesta de arriba, mientras dp[c−1] ya guarda la respuesta nueva de la izquierda. Esta interpretación permite usar O(columnas) memoria. El programa lee dimensiones y filas con punto para libre y numeral para obstáculo, y cuenta módulo 1000000007.\n\nEl mismo esquema puede minimizar costos, pero entonces reemplazas la suma de caminos por el mínimo de costos más el costo de entrar.",code:'#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\nint main(){ int n,m; cin>>n>>m; vector<long long> dp(m); for(int r=0;r<n;r++){ string s; cin>>s; for(int c=0;c<m;c++){ if(s[c]==\'#\') dp[c]=0; else if(r==0&&c==0) dp[c]=1; else if(c) dp[c]=(dp[c]+dp[c-1])%1000000007; } } cout<<dp[m-1]<<"\\n"; }'},
{title:"Comprobar el tamaño y los movimientos",body:"Visitar cada casilla cuesta O(filas·columnas). Revisa que el tamaño del tablero permita ese recorrido completo. Si el tablero tiene coordenadas enormes y pocos obstáculos, necesitarás combinatoria u otra compresión. Permitir movimientos hacia arriba crea ciclos y rompe el orden empleado; para distancias uniformes convendría BFS.\n\nPractica en un tablero 2 por 4 con la segunda celda de la primera fila bloqueada: solo puedes bajar inmediatamente y después avanzar, así que queda un camino. Comprueba también un tablero de una sola celda."}
],'En un tablero 2×3 libre con movimientos derecha/abajo, ¿cuántos caminos hay?',['2','3','4','6'],1,'Cada camino tiene dos movimientos a la derecha y uno hacia abajo. Elegir la posición del movimiento vertical da tres posibilidades.'),
G('lis','Subsecuencia creciente más larga',['usaco-gold-intro-dp','usaco-silver-binary-search-sorted-array'],['Distinguir subsecuencia de subarreglo','Mantener finales óptimos con búsqueda binaria'],[
{title:"Elegir valores sin cambiar su orden",body:"Una subsecuencia se forma borrando algunos elementos, sin mover los que quedan. En [3,1,2,5,4], [1,2,4] es creciente aunque sus posiciones no sean consecutivas. Define primero dp[i] como la longitud máxima de una subsecuencia estrictamente creciente que termina exactamente en i. La recurrencia es uno más el máximo dp[j] entre j<i con a[j]<a[i], o uno si no existe tal j.\n\nEsta definición O(n²) sirve para comprender y comprobar soluciones rápidas."},
{title:"Guardar el menor final para cada longitud",body:"Llama tails[k] al menor valor con el que puede terminar una subsecuencia creciente de longitud k+1 entre los elementos que ya leíste. Un final pequeño deja más opciones futuras. Al procesar 3,1,2,5,4, la lista evoluciona [3], [1], [1,2], [1,2,5], [1,2,4]. Su tamaño final es tres. La lista de finales no necesariamente constituye una subsecuencia real: cada posición puede provenir de decisiones históricas distintas.\n\nPara recuperar el recorrido debes guardar predecesores e índices."},
{title:"Encontrar dónde colocar el nuevo valor",body:"Los valores de tails están en orden estrictamente creciente: eso permite localizar con búsqueda binaria el que quieres reemplazar. Para un nuevo x, sustituye el primer final mayor o igual que x usando lower_bound, o agrégalo si no existe. Esto mejora el final sin cambiar las longitudes previamente alcanzables.\n\nSi buscas una subsecuencia no decreciente, usa upper_bound, el primer valor estrictamente mayor, porque los iguales sí pueden extender una subsecuencia. El programa imprime solamente la longitud estrictamente creciente.",code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main(){ int n; cin>>n; vector<long long> t; while(n--){ long long x; cin>>x; auto p=lower_bound(t.begin(),t.end(),x); if(p==t.end()) t.push_back(x); else *p=x; } cout<<t.size()<<"\\n"; }'},
{title:"Elegir entre dos soluciones",body:"La tabla que compara todos los pares cuesta O(n²); la de mejores finales usa búsqueda binaria y cuesta O(n log n). Ordenar la entrada no es una optimización válida: destruiría precisamente la condición de orden original. Prueba [2,2,2], cuya respuesta estricta es uno y cuya respuesta no decreciente es tres. Como ejercicio, adapta la versión cuadrática para contar cuántas subsecuencias de longitud máxima existen.\n\nNecesitarás combinar longitudes y cantidades, no basta con observar el tamaño de tails."}
],'¿Cuál es la LIS estricta de [4,1,2,2,3]?',['2','3','4','5'],1,'La subsecuencia [1,2,3] tiene longitud tres; usar ambos doses violaría el crecimiento estricto.'),
G('dp-bitmasks','DP con máscaras de bits',['usaco-gold-intro-dp','usaco-silver-intro-bitwise'],['Representar conjuntos pequeños como enteros','Separar estado visitado y último elemento'],[
{title:"Escribir un conjunto con bits",body:"Con alrededor de veinte elementos, puedes representar un subconjunto con una máscara de n bits: uno por elemento. El bit i vale uno si el elemento i está incluido. Esta representación no reduce los 2^n conjuntos existentes, pero vuelve compactas las operaciones de pertenencia, inserción y eliminación.\n\nUna DP puede compartir resultados entre órdenes diferentes que llegan al mismo conjunto, siempre que el futuro dependa solo de la información guardada."},
{title:"Una persona y una tarea por decisión",body:"Empecemos con tres estudiantes y tres tareas; cada estudiante debe recibir una tarea diferente. Sea dp[mask] el número de formas de asignar las primeras popcount(mask) personas a las tareas marcadas. Partimos de dp[0]=1. Para cada tarea libre compatible con la siguiente persona, sumamos dp[mask] a dp[mask | (1<<tarea)].\n\nSi todas las asignaciones están permitidas, las máscaras de un bit tienen uno, las de dos bits tienen dos y la máscara 111 termina con seis, que coincide con 3!."},
{title:"Cuando también importa dónde terminas",body:"Un camino hamiltoniano visita cada vértice una vez. Para contarlo, el estado necesita recordar tanto el conjunto visitado como el último vértice del camino. Usa dp[mask][v]. Desde un estado válido, agrega un vecino u no visitado y acumula en dp[mask|(1<<u)][u]. Si todos los caminos comienzan en s, inicializa únicamente dp[1<<s][s]=1.\n\nEl invariante afirma que cada secuencia contada usa exactamente los vértices de mask y termina en v, evitando mezclar caminos incompatibles."},
{title:"Calcular el tamaño de la tabla",body:"La asignación usa O(n·2^n) tiempo y O(2^n) memoria: hay una respuesta por máscara y hasta n tareas para probar. La transición densa de caminos puede costar O(n²·2^n) y memoria O(n·2^n), que crece rápidamente. No reserves esta tabla para n=40. Usa tipos sin signo o tamaños seguros al desplazar bits; un desplazamiento igual al ancho del tipo es inválido.\n\nComo ejercicio, restringe a la primera persona para que solo haga tarea cero: quedan dos asignaciones completas. Deriva también una versión que minimice costos reemplazando suma por mínimo."}
],'En dp[mask] para asignaciones, ¿qué persona se asigna a continuación?',['La de índice popcount(mask)','La de índice mask','Siempre la última'],0,'Los bits cuentan tareas ya ocupadas; se ha asignado exactamente esa misma cantidad de personas iniciales.'),
G('dp-ranges','Programación dinámica en intervalos',['usaco-gold-intro-dp','usaco-silver-prefix-sums'],['Definir estados sobre segmentos contiguos','Elegir el último corte o la última operación'],[
{title:"Guardar una respuesta por intervalo",body:"Cuando solo puedes combinar elementos vecinos, define dp[l][r] como la mejor respuesta para el tramo completo entre l y r. No cualquier pareja de índices funciona automáticamente; debes demostrar que, fijadas las fronteras, no necesitas saber cómo se resolvió el exterior. Los problemas de fusionar montones, parentizar productos y juegos sobre extremos suelen compartir esta estructura aunque sus transiciones sean distintas."},
{title:"Comparar el orden de las uniones",body:"Usaremos tres montones de tamaños [2,3,4] y solo podremos unir dos montones vecinos en cada operación. Fusionar dos vecinos cuesta la suma de sus tamaños. Si primero unes 2 y 3, pagas cinco y después nueve: total catorce. Si unes 3 y 4 primero, pagas siete y luego nueve: total dieciséis. Sea S(l,r) la suma del intervalo. El último paso une [l,k] y [k+1,r], así que dp[l][r]=min_k(dp[l][k]+dp[k+1][r]+S(l,r)).\n\nPara un solo montón el costo es cero."},
{title:"Resolver primero los tramos más cortos",body:"Llena la tabla por longitudes: primero intervalos de un elemento, luego de dos y así hasta el arreglo completo. Todos los intervalos usados por la transición son más cortos que el actual; esa es la prueba de que ya están disponibles. Un arreglo de prefijos calcula S(l,r) en O(1). Para reconstruir las fusiones, guarda el corte k que logró cada mínimo y recorre ambos subintervalos.\n\nEmpates pueden resolverse con cualquier regla consistente si solo piden un óptimo."},
{title:"Cuántos intervalos y cortes hay",body:"Hay O(n²) intervalos y hasta O(n) cortes en cada uno: necesitas O(n³) tiempo y O(n²) memoria. La restricción de contigüidad es esencial: permitir fusionar cualquier par conduce a otro problema. No apliques una optimización de cortes monótonos sin probar sus condiciones, aunque ejemplos pequeños la sugieran. Practica [1,1,1,1]: fusionar parejas cuesta 2+2 y unirlas cuesta cuatro, total ocho.\n\nCompara con fusionar siempre desde la izquierda, que cuesta 2+3+4=9, para descartar esa regla voraz."}
],'Para fusionar [2,3,4], ¿cuál es el costo óptimo?',['9','12','14','16'],2,'Fusionar 2 y 3 cuesta 5; fusionar el montón de 5 con 4 cuesta 9. Total 14.'),
G('digit-dp','DP por dígitos y límites numéricos',['usaco-gold-intro-dp'],['Contar enteros sin recorrer el rango','Controlar prefijos ajustados y ceros iniciales'],[
{title:"Construir números por sus cifras",body:"Recorrer todos los enteros hasta 10¹⁸ requiere demasiado tiempo, pero construir un número solo necesita decidir unas pocas cifras. La DP por dígitos construye prefijos y reúne aquellos con el mismo comportamiento futuro. Un estado suele incluir posición, información de la propiedad y tight: si el prefijo coincide todavía con el del límite. También puede incluir started para distinguir ceros iniciales de dígitos pertenecientes al número."},
{title:"Un conteo que puedes revisar a mano",body:"Queremos contar los enteros de cero a 25 cuya suma de cifras sea múltiplo de tres. El estado lleva el residuo de la suma módulo tres. Las respuestas son 0,3,6,9,12,15,18,21,24: nueve números. Si eliges primera cifra uno, ya eres menor que el prefijo dos del límite y la segunda cifra puede ser cualquiera.\n\nSi eliges dos, tight sigue activo y la segunda cifra solo puede ir de cero a cinco."},
{title:"Definir la respuesta de un prefijo",body:"F(pos,residuo,tight) cuenta cuántas terminaciones válidas puedes agregar al prefijo que ya construiste. El máximo dígito permitido es la cifra del límite si tight vale verdadero, o nueve en caso contrario. Para cada d, suma F(pos+1,(residuo+d)%3,tight && d==cifraDelLímite). Al agotar posiciones devuelve uno si residuo es cero y cero si no.\n\nPara esta propiedad los ceros iniciales son inocuos; para contar números que contienen el dígito cero debes agregar started y tratar el número cero explícitamente."},
{title:"Pasar de un límite a dos",body:"Con L cifras y S estados de la propiedad, el costo es O(L·S·10), además de las pequeñas banderas del estado; la memoria es O(L·S). Un intervalo [a,b] se resuelve como contar(b)−contar(a−1), definiendo contar(x)=0 para x<0. No reutilices estados tight entre límites distintos sin limpiar la memoria. Practica contar hasta 25 números sin dígitos consecutivos iguales: los ceros de relleno no deben hacer inválidos los números de una cifra.\n\nComprueba primero todos los números hasta cien con una solución exhaustiva."}
],'Si el prefijo elegido ya es menor que el del límite, ¿qué ocurre con tight?',['Vuelve a verdadero en la siguiente cifra','Permanece falso','Impide elegir cero'],1,'Una diferencia en una cifra más significativa ya garantiza que todo sufijo produce un número menor.'),
G('unweighted-shortest-paths','BFS y caminos con pesos cero o uno',['usaco-silver-graph-traversal'],['Probar la distancia mínima por capas','Elegir cola o deque según los pesos'],[
{title:"Una arista equivale a un paso",body:"Si todas las aristas cuestan lo mismo, buscar el camino más corto equivale a usar la menor cantidad de aristas. Una cola conserva este orden de capas. Define dist[v]=−1 para no visitado y dist[s]=0. Cuando descubres u desde v, asigna dist[u]=dist[v]+1 y encola u. Marca al descubrir, no al extraer, para evitar que varios vecinos encolen repetidamente el mismo vértice."},
{title:"Ver las capas en un grafo pequeño",body:"Con aristas 0–1, 0–2, 1–3, 2–3 y 3–4, las capas desde cero son {0}, {1,2}, {3} y {4}. La distancia de cero a cuatro es tres. Guarda padre[u]=v cuando lo descubres y retrocede desde el destino para recuperar una ruta. Puede haber varias rutas mínimas y BFS devolverá una según el orden de adyacencia.\n\nLa prueba consiste en observar que ninguna arista desde una capa futura puede mejorar una distancia ya asignada."},
{title:"Leer el grafo y ampliar el recorrido",body:"El programa lee n, m y las aristas de un grafo sin dirección, con índices desde cero. Después imprime las distancias desde el vértice cero. Si hay varias fuentes, inicializa todas con distancia cero en la misma cola. Para aristas de costo cero o uno, usa 0–1 BFS: relaja distancias, coloca mejoras por costo cero al frente de una deque y por costo uno al fondo.\n\nLa primera visita simple ya no sustituye a una relajación.",code:'#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main(){ int n,m; cin>>n>>m; vector<vector<int>> g(n); while(m--){ int a,b; cin>>a>>b; g[a].push_back(b); g[b].push_back(a); } vector<int>d(n,-1); queue<int>q; d[0]=0; q.push(0); while(!q.empty()){ int v=q.front(); q.pop(); for(int u:g[v]) if(d[u]==-1){ d[u]=d[v]+1; q.push(u); } } for(int x:d) cout<<x<<" "; cout<<"\\n"; }'},
{title:"Contar el trabajo de vértices y aristas",body:"Con listas de vecinos, BFS cuesta O(n+m) tiempo y O(n+m) memoria contando el grafo. La variante para pesos cero y uno también puede ser lineal. No uses BFS ordinario para costos arbitrarios: una ruta con menos aristas puede ser más cara. Practica modelando un tablero como grafo implícito y una llave como estado adicional: (fila,columna,tieneLlave).\n\nDos visitas a la misma celda con distinta llave son estados distintos porque ofrecen movimientos futuros diferentes."}
],'En el ejemplo, ¿qué distancia tiene el vértice 4 desde 0?',['2','3','4'],1,'Se necesita llegar a 1 o 2, después a 3 y después a 4: tres aristas.'),
G('dsu','Conjuntos disjuntos y conectividad',['usaco-silver-graph-traversal'],['Mantener componentes al agregar conexiones','Usar tamaño y compresión de caminos'],[
{title:"Mantener grupos separados",body:"DSU es una estructura de conjuntos disjuntos: cada elemento pertenece a un solo grupo, y puedes juntar grupos sin recorrer todos sus elementos. find(v) devuelve un representante del grupo de v y unite(a,b) combina dos grupos. No conserva las aristas ni describe una ruta entre vértices: solo responde pertenencia a componentes. Funciona especialmente bien cuando las conexiones se agregan y las componentes solo se fusionan.\n\nQuitar una arista puede dividir un grupo y requiere técnicas adicionales."},
{title:"Seguir tres uniones",body:"Empieza con cinco estudiantes, cada uno en su propio grupo. Agrega 0–1 y 2–3: quedan {0,1}, {2,3}, {4}. Agrega 1–2 y obtienes {0,1,2,3}, {4}. Una nueva conexión 0–3 no reduce la cantidad de componentes porque sus representantes ya coinciden. El invariante es que cada conjunto forma un árbol de padres cuya raíz es su representante.\n\nLa identidad numérica de la raíz no importa; no supongas que será el menor elemento."},
{title:"Unir por tamaño y acortar búsquedas",body:"Al unir dos grupos, coloca la raíz del menor debajo de la raíz del mayor y actualiza el tamaño del grupo resultante. La compresión de caminos conecta cada vértice visitado por find directamente con la raíz encontrada. Ambas preservan la partición aunque cambien la forma interna del árbol. El programa recibe n y m conexiones y muestra cuántas componentes quedan.\n\nEl valor de size solo es fiable en las raíces.",code:'#include <iostream>\n#include <vector>\n#include <numeric>\n#include <algorithm>\nusing namespace std;\nstruct DSU{ vector<int>p,s; DSU(int n):p(n),s(n,1){iota(p.begin(),p.end(),0);} int find(int x){return p[x]==x?x:p[x]=find(p[x]);} bool join(int a,int b){a=find(a);b=find(b);if(a==b)return false;if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];return true;} };\nint main(){int n,m;cin>>n>>m;DSU d(n);int components=n;while(m--){int a,b;cin>>a>>b;components-=d.join(a,b);}cout<<components<<"\\n";}'},
{title:"El costo de muchas operaciones",body:"Con unión por tamaño y compresión de caminos, la secuencia cuesta O((n+m)α(n)). La función α, inversa de Ackermann, crece tan despacio que es muy pequeña para tamaños habituales. El espacio adicional es O(n). Es una cota amortizada, no una promesa de exactamente una operación por consulta. Practica detectando la primera arista que crea un ciclo en un grafo no dirigido: ocurre cuando sus extremos ya estaban conectados.\n\nExplica por qué esa prueba no detecta del mismo modo ciclos dirigidos, pues la conectividad ignora la orientación."}
],'Después de unir 0–1, 2–3 y 1–2 en cinco elementos, ¿cuántos grupos quedan?',['1','2','3','4'],1,'Los cuatro primeros elementos forman un grupo y el elemento 4 permanece solo: dos grupos.'),
G('toposort','Orden topológico y DP en DAG',['usaco-silver-graph-traversal','usaco-gold-intro-dp'],['Ordenar tareas con dependencias','Detectar ciclos y propagar estados'],[
{title:"Hacer una tarea después de sus requisitos",body:"Si una tarea depende de otra, el orden debe colocar primero el requisito. Un orden topológico acomoda los vértices de un grafo dirigido de modo que toda arista vaya hacia adelante. Existe cuando el grafo no tiene ciclos dirigidos. Puede haber muchos órdenes válidos; el algoritmo no necesita elegir uno único salvo que el problema pida, por ejemplo, el menor lexicográficamente."},
{title:"Encontrar las tareas disponibles",body:"Kahn guarda el grado de entrada de cada vértice, es decir, cuántas dependencias llegan a él. Encola todos los que no tienen requisitos pendientes. Al extraer v, lo agrega al orden y reduce los grados de sus sucesores; los que llegan a cero pasan a estar disponibles. Con aristas 0→2, 1→2, 2→3, puedes producir 0,1,2,3 o 1,0,2,3.\n\nSi hay un ciclo 2→3→2, ninguno de sus vértices puede quedar listo después de quitar todos los requisitos externos."},
{title:"Detectar si falta procesar vértices",body:"El programa imprime un orden válido cuando consigue procesar todos los vértices; si faltan algunos, imprime CICLO. Sobre el orden puedes contar caminos con ways[u]+=ways[v] para cada arista v→u, o hallar la mayor longitud con best[u]=max(best[u],best[v]+1). Debes inicializar la fuente según el problema; poner uno en todos los vértices cuenta caminos que empiezan en cualquiera, que es otra pregunta.",code:'#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;vector<vector<int>>g(n);vector<int>in(n),order;while(m--){int a,b;cin>>a>>b;g[a].push_back(b);in[b]++;}queue<int>q;for(int i=0;i<n;i++)if(!in[i])q.push(i);while(!q.empty()){int v=q.front();q.pop();order.push_back(v);for(int u:g[v])if(--in[u]==0)q.push(u);}if((int)order.size()!=n)cout<<"CICLO\\n";else{for(int v:order)cout<<v<<" ";cout<<"\\n";}}'},
{title:"El costo del orden topológico",body:"Construir el orden requiere O(n+m) tiempo y O(n+m) memoria, incluyendo las listas de aristas. La DP adicional también es lineal si cada transición cuesta constante. Un grafo puede tener ciclos en una componente desconectada: procesar desde una sola fuente no basta para certificar que todo el grafo es DAG.\n\nComo ejercicio, agrega 0→3 al ejemplo y cuenta caminos de cero a tres: hay dos, el directo y el que pasa por dos. Después añade 3→0 y explica por qué desaparece cualquier orden válido."}
],'Si Kahn procesa solo 7 de 10 vértices, ¿qué concluyes?',['El grafo tiene un ciclo dirigido','Los tres restantes están aislados','Se necesita DFS para decidir'],0,'Todo DAG no vacío tiene un vértice de entrada cero. Si quedan vértices y ninguno está listo, hay un ciclo dirigido.'),
G('shortest-paths','Dijkstra y rutas con pesos',['usaco-gold-unweighted-shortest-paths','usaco-silver-priority-queues'],['Relajar aristas ponderadas','Justificar la condición de pesos no negativos'],[
{title:"Sumar costos en lugar de contar aristas",body:"Una carretera directa puede costar cinco y dos carreteras consecutivas pueden costar uno más dos: la segunda ruta resulta más barata. Para pesos no negativos, Dijkstra mantiene distancias tentativas y elige siempre el vértice pendiente con menor valor. La operación fundamental es relajar v→u: si dist[v]+peso mejora dist[u], actualizamos la estimación. Una cola de prioridad permite encontrar rápidamente el siguiente candidato sin revisar todos los vértices cada vez."},
{title:"Mejorar una distancia conocida",body:"En el grafo 0→1 de costo cinco, 0→2 de costo uno y 2→1 de costo dos, primero conocemos distancias [0,5,1]. Sacamos el vértice dos antes que el uno y mejoramos dist[1] a tres. La ruta óptima no es la de una sola arista.\n\nLa prueba usa pesos no negativos: cualquier ruta alternativa que atraviese un vértice todavía más lejano no puede regresar con una distancia menor al mínimo extraído."},
{title:"Descartar propuestas que ya mejoraron",body:"Cuando encuentras una ruta mejor, puedes insertar su nueva distancia en el montículo y dejar allí la propuesta anterior. Al sacar (d,v), si d no coincide con dist[v], lo ignora. Esto evita procesar de nuevo todas las aristas de una estimación obsoleta. El programa usa un grafo dirigido y supone que todos los pesos son no negativos y las distancias relevantes menores que 4·10¹⁸.",code:'#include <iostream>\n#include <vector>\n#include <queue>\n#include <functional>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;using P=pair<long long,int>;vector<vector<P>>g(n);while(m--){int a,b;long long w;cin>>a>>b>>w;g[a].push_back({w,b});}const long long INF=4000000000000000000LL;vector<long long>d(n,INF);priority_queue<P,vector<P>,greater<P>>q;d[0]=0;q.push({0,0});while(!q.empty()){auto [x,v]=q.top();q.pop();if(x!=d[v])continue;for(auto [w,u]:g[v])if(w<=INF-x && x+w<d[u]){d[u]=x+w;q.push({d[u],u});}}for(auto x:d)cout<<(x==INF?-1:x)<<" ";cout<<"\\n";}'},
{title:"Cuándo usar Dijkstra",body:"Con un montículo y propuestas duplicadas, Dijkstra requiere O((n+m)log(n+m)) tiempo y O(n+m) memoria. Para un grafo simple se suele expresar O((n+m)log n). Pesos negativos rompen la prueba, aunque no exista ciclo negativo. En DAG puedes calcular distancias en orden topológico incluso con pesos negativos; para grafos generales estudia Bellman–Ford.\n\nPractica agregando 1→3 con peso cuatro y 2→3 con peso diez: la mejor distancia a tres es siete, pasando por dos y uno."}
],'¿Qué condición exige la prueba habitual de Dijkstra?',['Pesos todos distintos','Pesos no negativos','Grafo sin ciclos','Una sola ruta por vértice'],1,'Los pesos no negativos impiden que continuar una ruta desde una distancia mayor produzca una distancia total menor.'),
G('mst','Árbol de expansión mínima',['usaco-gold-dsu','usaco-silver-greedy-sorting'],['Distinguir conectar todo de hallar rutas cortas','Justificar Kruskal mediante cortes'],[
{title:"Tender una red de cables",body:"Quieres conectar varias escuelas y pagar cada cable una sola vez; buscas que todas queden comunicadas al menor costo. El objetivo suma las aristas elegidas, no las distancias desde una escuela. En un grafo no dirigido y conectado, una solución óptima puede ser un árbol de expansión con n−1 aristas.\n\nSi una solución incluye un ciclo, se puede eliminar una de sus aristas sin perder conectividad; con costos no negativos esto nunca empeora el costo."},
{title:"Elegir aristas sin cerrar ciclos",body:"En un triángulo con pesos 2, 3 y 7, toma las aristas de peso 2 y 3: ya conectan todo con costo 5. La siete formaría un ciclo y se descarta. El total óptimo es cinco. Kruskal procesa aristas en orden creciente y agrega una cuando une componentes distintas del DSU.\n\nLa propiedad del corte justifica la elección: una arista mínima que cruza entre una componente actual y el resto puede pertenecer a algún árbol óptimo compatible con lo ya seleccionado."},
{title:"Comparar una elección con un árbol óptimo",body:"Para justificar una arista e de Kruskal, toma un árbol óptimo que todavía no la use y agrégasela. Al agregar e aparece un ciclo. Ese ciclo contiene otra arista f que cruza el mismo corte; por la elección mínima, peso(e)≤peso(f). Sustituir f por e mantiene un árbol y no aumenta su costo. Repetir este intercambio demuestra que las decisiones voraces pueden extenderse a un óptimo.\n\nLos empates pueden producir árboles diferentes con el mismo costo, lo cual es completamente válido."},
{title:"Detectar si falta conectar algún vértice",body:"Ordenar las aristas cuesta O(m log m), las operaciones de DSU añaden O(mα(n)) y la memoria total es O(n+m). Si al terminar hay menos de n−1 aristas elegidas, el grafo no era conectado y obtuviste un bosque mínimo. Los pesos negativos también son compatibles con Kruskal cuando buscamos un árbol; la explicación de eliminar ciclos de una red arbitraria debe matizarse entonces.\n\nPractica un cuadrado con lados de peso uno y diagonales de peso diez: cualquier selección de tres lados que conecte los cuatro vértices cuesta tres. Comprueba que su ruta entre dos vértices no necesariamente coincide con la ruta mínima del grafo original."}
],'¿Cuántas aristas tiene un árbol de expansión de ocho vértices?',['6','7','8','Depende de los pesos'],1,'Todo árbol conectado de n vértices tiene n−1 aristas; para ocho son siete.'),
G('intro-sorted-sets','Conjuntos ordenados y búsquedas por vecino',['usaco-bronze-intro-sets','usaco-silver-binary-search-sorted-array'],['Usar set y multiset con límites','Elegir una estructura según las operaciones'],[
{title:"Mantener los precios en orden",body:"Un set guarda valores distintos en orden; un multiset conserva también las copias repetidas. Ambos soportan insertar, encontrar y eliminar sin ordenar todo nuevamente. Son útiles para localizar el primer valor al menos x, su predecesor o el mínimo actual mientras llegan cambios. No confundir este orden con el orden de inserción: el recorrido de un set sigue su comparador, aunque los elementos hayan llegado de manera diferente."},
{title:"Vender un boleto que quepa en el presupuesto",body:"Con precios [3,5,5,8] y presupuesto seis, necesitas el boleto más caro que no supere ese límite. En el multiset, upper_bound(6) apunta a ocho; su predecesor es cinco, el boleto más caro que aún cabe. Elimina solo ese iterador para conservar el otro cinco. Si upper_bound apunta al inicio, no existe boleto admisible. Para consultar el primer precio al menos cinco, lower_bound(5) devuelve una de las apariciones de cinco."},
{title:"Comprobar los extremos antes de leer",body:"El conjunto mantiene el orden por ti, pero debes comprobar si un iterador señala un elemento antes de usarlo. Antes de dereferenciar, comprueba que el iterador no sea end; antes de retroceder, comprueba que no sea begin. En multiset, erase(valor) borra todas las apariciones equivalentes, mientras erase(iterador) borra una.\n\nUsa el método miembro lower_bound del conjunto: el algoritmo genérico aplicado a iteradores de árbol puede requerir avance lineal aunque haga pocas comparaciones."},
{title:"Qué operaciones son rápidas",body:"Buscar e insertar cuesta O(log n), y guardar n elementos ocupa O(n) memoria. Encontrar el k-ésimo elemento avanzando un iterador cuesta O(k): set estándar no ofrece estadísticas de orden en tiempo logarítmico. Si todos los cambios están en posiciones conocidas, un Fenwick con frecuencias puede ser mejor. Practica procesando presupuestos [6,6,2,10] con los boletos del ejemplo; vendes cinco, cinco, ninguno y ocho.\n\nExplica por qué un vector ordenado más borrados intermedios puede terminar costando O(n²) en una secuencia larga."}
],'¿Qué elimina exactamente una aparición de 5 de un multiset?',['erase(5)','erase(find(5)), si existe','clear()'],1,'erase(valor) elimina todas las claves equivalentes; erase(iterador) elimina únicamente el elemento señalado.'),
G('custom-cpp-stl','Comparadores personalizados en contenedores',['usaco-silver-sorting-custom','usaco-gold-intro-sorted-sets'],['Definir un orden estricto coherente','Entender equivalencia y prioridad'],[
{title:"Ordenar registros con varios datos",body:"Para ordenar por puntuación descendente y después por identificador ascendente, escribe esas dos decisiones en el comparador. Si quieres ordenar por mayor puntuación y, en empate, menor identificador, el comparador debe expresar exactamente esa relación. En sort y set, comp(a,b) significa que a debe aparecer antes que b.\n\nLa biblioteca necesita un orden débil estricto: ningún elemento debe precederse a sí mismo y las comparaciones deben ser coherentes y transitivas. Usar menor o igual viola la primera condición."},
{title:"Resolver un empate de puntuación",body:"Ana tiene 90 puntos e id 2; Beto, 90 e id 1; Carla, 75 e id 3. El orden deseado es Beto, Ana, Carla. Compara primero puntuación con mayor que y después identificador con menor que. Si en un set comparas únicamente puntuaciones, Ana y Beto resultan equivalentes porque ninguna precede a la otra; el conjunto conservará solo uno, aunque sean personas distintas."},
{title:"Entender el comparador de cada contenedor",body:"Puedes escribir el criterio como una función o como un objeto con operator(), siempre que mantenga el mismo orden durante su uso. Mantén el criterio estable mientras los elementos estén almacenados; cambiar datos externos usados por el comparador puede invalidar el orden del contenedor. En priority_queue, el elemento con mayor prioridad queda arriba respecto al orden del comparador: greater<int> crea un mínimo arriba.\n\nComprueba siempre un ejemplo de dos elementos antes de asumir que el mismo criterio sirve igual para ordenar e programar una cola."},
{title:"Contar también el trabajo de comparar",body:"Si el comparador cuesta O(1), sort tarda O(n log n), las operaciones de set O(log n) y push/pop del montículo O(log n). Si comparar examina cadenas largas, ese costo se multiplica y debe contarse. Evita restar enteros para decidir el orden, porque la resta puede desbordarse; compara directamente. Practica almacenando solicitudes por fecha ascendente y urgencia descendente, con identificador como último desempate.\n\nEscribe los resultados esperados para tres solicitudes con la misma fecha y comprueba irreflexividad y transitividad con casos manuales."}
],'Si un set compara solo puntuación, ¿qué ocurre con dos personas de 90 puntos?',['Siempre guarda las dos','Las considera equivalentes','Ordena por nombre automáticamente'],1,'Si comp(a,b) y comp(b,a) son ambos falsos, set trata las claves como equivalentes y no admite ambas.' ,true),
G('stacks','Pilas monótonas y vecinos relevantes',['usaco-bronze-intro-ds'],['Encontrar el vecino menor en tiempo lineal','Probar el costo amortizado de una pila'],[
{title:"Guardar candidatos en una pila",body:"Una pila permite agregar y quitar por un solo extremo, como una pila de platos donde solo tomas el de arriba. Una pila monótona conserva valores en orden creciente o decreciente para responder preguntas sobre el vecino anterior o siguiente que cumple una comparación.\n\nLa posición también importa. Solo retiras un candidato cuando uno más reciente puede reemplazarlo en cualquier consulta futura."},
{title:"Buscar un menor a la izquierda",body:"Para [4,2,5,1,3], queremos saber qué posición anterior y más cercana tiene un valor estrictamente menor. Al llegar a dos, sacamos cuatro porque no es menor y nunca será mejor candidato que el dos reciente. Al llegar a cinco, el dos queda arriba. Al llegar a uno, salen cinco y dos. Los índices de respuesta, usando cero y −1 para ausencia, son [−1,−1,1,−1,3]."},
{title:"Retirar antes de consultar",body:"Guarda índices con valores crecientes; antes de responder para x, retira del tope los valores mayores o iguales que x. Para procesar x, sacamos mientras el valor superior sea mayor o igual que x, consultamos el superior restante y finalmente insertamos el índice actual. El signo igual importa si la pregunta pide estrictamente menor. El programa lee un arreglo y muestra los índices pedidos.\n\nGuardar índices, en lugar de solo valores, permite calcular distancias y resolver empates correctamente.",code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int n;cin>>n;vector<long long>a(n);vector<int>s;for(int i=0;i<n;i++){cin>>a[i];while(!s.empty()&&a[s.back()]>=a[i])s.pop_back();cout<<(s.empty()?-1:s.back())<<" ";s.push_back(i);}cout<<"\\n";}'},
{title:"Contar entradas y salidas",body:"Cada índice entra una vez y sale como máximo una vez. Por eso el recorrido completo tarda O(n) y guarda O(n) datos, aunque tenga un while dentro del for. Esta amortización aparece también al resolver histogramas y contribuciones de mínimos. Para contar contribuciones con valores repetidos debes repartir los empates, por ejemplo usando estricta de un lado y no estricta del otro.\n\nPractica el arreglo [2,2,1]: con menor estricto no hay respuesta en ninguna posición; con menor o igual, la segunda posición sí encuentra la primera."}
],'¿Por qué una pila monótona tarda O(n) aunque tenga un while interno?',['El while siempre ejecuta una vez','Cada elemento entra y sale a lo sumo una vez','Los datos ya están ordenados'],1,'Sumando todas las iteraciones, hay n inserciones y como máximo n extracciones, independientemente de cómo se distribuyan.'),
G('sliding-window','Ventanas deslizantes y deque monótona',['usaco-silver-two-pointers','usaco-gold-stacks'],['Mantener máximos al mover una ventana','Distinguir ventanas fijas de condiciones monótonas'],[
{title:"Mover un tramo de tamaño fijo",body:"Una ventana es un tramo contiguo; al avanzar una posición, sale su primer elemento y entra uno al final. Para una longitud fija k, cada paso elimina el elemento más antiguo e incorpora uno nuevo. Sumas pueden actualizarse restando y sumando; máximos necesitan una estructura que recuerde candidatos. Un multiset ofrece O(log k) por cambio, mientras una deque monótona aprovecha que los índices entran y salen en orden."},
{title:"Conservar los candidatos al máximo",body:"En [2,1,5,3,4], cada ventana de longitud tres tiene máximo cinco. Cuando entra cinco, podemos descartar dos y uno: cinco es mayor y permanecerá en las ventanas futuras al menos tanto como ellos. Guardamos índices en orden creciente, con valores decrecientes. El frente representa el máximo. Antes de responder, quitamos del frente los índices que quedaron fuera de [i−k+1,i]."},
{title:"Quitar por delante o por detrás",body:"De la deque salen por delante los índices vencidos y por detrás los candidatos que el nuevo valor ya supera. El programa admite 1≤k≤n. Los valores pueden ser negativos: la validez del máximo deslizante no depende de su signo. Para ventanas variables sujetas a suma≤T, en cambio, mover únicamente la izquierda para reparar excesos requiere supuestos como valores no negativos; no transfieras esa condición sin demostrarla.",code:'#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\nint main(){int n,k;cin>>n>>k;if(k<1||k>n)return 0;vector<long long>a(n);deque<int>q;for(int i=0;i<n;i++){cin>>a[i];while(!q.empty()&&q.front()<=i-k)q.pop_front();while(!q.empty()&&a[q.back()]<=a[i])q.pop_back();q.push_back(i);if(i>=k-1)cout<<a[q.front()]<<" ";}cout<<"\\n";}'},
{title:"Calcular el costo total",body:"Cada índice entra y sale una vez: el tiempo total es O(n) y la deque necesita O(k) memoria, además del arreglo de este ejemplo. Una cola hecha con dos pilas puede mantener agregados asociativos cuando no existe una dominancia útil, como máximo común divisor. Practica mínimos de longitud dos en [−1,4,−3,2], que dan [−1,−3,−3].\n\nDespués construye un contraejemplo que muestre por qué una ventana para suma máxima con negativos no se arregla usando una regla basada solo en superar un límite."}
],'¿Qué se elimina por el frente de una deque de máximos?',['Índices que ya salieron de la ventana','Todos los valores negativos','Solo valores menores al nuevo'],0,'El frente elimina candidatos vencidos por posición; los candidatos dominados por valor se eliminan por atrás.'),
G('PURS','Actualización puntual y suma de rango',['usaco-silver-prefix-sums'],['Implementar Fenwick con índices desde uno','Comparar Fenwick y árbol de segmentos'],[
{title:"Una suma que debe aceptar cambios",body:"Una tabla de prefijos responde cada suma en O(1), pero cambiar un elemento obliga a corregir todos los prefijos posteriores. Fenwick reparte la información en bloques para aceptar tanto cambios puntuales como consultas de prefijo en O(log n).\n\nNumera desde uno. La entrada i guarda un bloque que termina en i y mide lowbit(i)=i&−i. Por ejemplo, lowbit(6)=2: esa entrada suma las posiciones cinco y seis. Cada bloque se conserva actualizado cuando cambian los elementos que contiene."},
{title:"Sumar bloques sin repetir posiciones",body:"El prefijo de siete usa las entradas siete, seis y cuatro, que guardan [7,7], [5,6] y [1,4]. Juntas cubren [1,7] sin repetir posiciones. Luego la suma inclusiva [l,r] es prefijo(r)−prefijo(l−1). Con arreglo [2,4,1,3], la suma [2,4] vale ocho. Si agregamos cinco a la posición tres, el arreglo queda [2,4,6,3] y esa consulta vale trece."},
{title:"Moverse entre los bloques",body:"La consulta resta i&−i al índice para saltar el bloque derecho que acaba de contar. Una actualización con delta avanza i+=i&−i para visitar todos los bloques que incluyen esa posición. El programa recibe operaciones: 1 índice delta agrega, y 2 l r consulta. Si el enunciado pide asignar un nuevo valor, conserva el anterior y agrega la diferencia; sumar directamente el nuevo valor resolvería una operación distinta.",code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int n,q;cin>>n>>q;vector<long long>b(n+1);auto add=[&](int i,long long x){for(;i<=n;i+=i&-i)b[i]+=x;};auto sum=[&](int i){long long s=0;for(;i>0;i-=i&-i)s+=b[i];return s;};for(int i=1;i<=n;i++){long long x;cin>>x;add(i,x);}while(q--){int t,l;long long r;cin>>t>>l>>r;if(t==1)add(l,r);else cout<<sum((int)r)-sum(l-1)<<"\\n";}}'},
{title:"Comparar Fenwick y árbol de segmentos",body:"Fenwick ocupa O(n) memoria y hace cada operación en O(log n). Construirlo con inserciones cuesta O(n log n), aunque también existe una construcción lineal. Un árbol de segmentos también permite estas operaciones y combina otras funciones asociativas como mínimo; la resta de prefijos no funciona para mínimos. Nunca actualices Fenwick en índice cero, pues lowbit(0)=0 produciría un bucle infinito.\n\nPractica una estructura de frecuencias para contar cuántos valores son menores que x después de comprimir coordenadas; justifica qué conserva la compresión."}
],'Si asignas 9 a una posición cuyo valor era 4, ¿qué delta agregas?',['4','5','9','13'],1,'La actualización aditiva debe cambiar 4 en 9: delta=9−4=5.'),
G('dp-trees','Programación dinámica sobre árboles',['usaco-silver-intro-tree','usaco-gold-intro-dp'],['Combinar respuestas de subárboles','Separar estados según la decisión en la raíz'],[
{title:"Resolver primero los subárboles",body:"Al elegir una raíz para un árbol, cada vértice queda a cargo de los descendientes que cuelgan de él. Muchas decisiones pueden combinarse después de resolver esos hijos, siempre que el estado describa lo que el padre necesita saber. El recorrido posorden procesa primero descendientes y luego el vértice actual. No basta con hacer DFS: debes explicar por qué no existe una interacción olvidada entre subárboles."},
{title:"Elegir vértices que no sean vecinos",body:"Si quieres elegir muchos vértices sin tomar dos conectados por una arista, la decisión sobre un padre restringe a sus hijos. Define dp[v][1] como el óptimo del subárbol si eliges v, y dp[v][0] si no lo eliges. Entonces dp[v][1]=1+Σ dp[hijo][0], mientras dp[v][0]=Σ max(dp[hijo][0],dp[hijo][1]). En una estrella con centro y cuatro hojas, elegir el centro da uno; excluirlo permite elegir las cuatro hojas, así que el óptimo es cuatro."},
{title:"Por qué puedes combinar respuestas de los hijos",body:"Si eliges v, cada hijo debe quedar fuera. Las decisiones sobre los nietos se resuelven dentro de las respuestas de esos hijos. Si v está excluido, cada hijo puede escoger su mejor estado independientemente porque no hay aristas entre subárboles distintos. Esta independencia prueba la transición por inducción sobre el tamaño del subárbol.\n\nPara recuperar los vértices elegidos, comienza con el mejor estado de la raíz y transmite a cada hijo la restricción correspondiente."},
{title:"Procesar el árbol sin llamadas profundas",body:"Hay dos estados por vértice y cada arista interviene una vez al combinar hijos: el costo es O(n) tiempo y O(n) memoria. Para un árbol en forma de cadena, una DFS recursiva profunda puede agotar la pila; puedes guardar un orden iterativo y procesarlo al revés. En un grafo con ciclos la misma fórmula cuenta dependencias incorrectamente.\n\nPractica con un camino de cinco vértices: elegir posiciones uno, tres y cinco da tres. Después cambia el valor uno por un peso del vértice y adapta la recurrencia al conjunto independiente de peso máximo."}
],'En una estrella con cuatro hojas, ¿cuál es el conjunto independiente máximo?',['Solo el centro, tamaño 1','Dos hojas, tamaño 2','Todas las hojas, tamaño 4'],2,'Las hojas no son adyacentes entre sí. Elegir las cuatro es válido y supera elegir únicamente el centro.'),
G('all-roots','Reenraizar: respuestas para todos los vértices',['usaco-gold-dp-trees'],['Reutilizar una solución al cambiar la raíz','Separar aportes del subárbol y del exterior'],[
{title:"Evitar un recorrido por cada origen",body:"Para sumar las distancias desde todos los orígenes, hacer una DFS completa desde cada vértice costaría O(n²). Vamos a reutilizar lo que cambia al movernos a un vecino. El reenraizamiento aprovecha que mover la raíz a un vecino modifica las distancias de forma predecible. Primero eliges una raíz cualquiera y calculas información de subárboles; luego recorres las aristas en sentido descendente para transferir respuestas ya conocidas."},
{title:"Qué cambia al mover la raíz",body:"Llama size[c] al tamaño del subárbol del hijo c y ans[v] a la suma de distancias desde v. Al mover el origen de v a c, los size[c] vértices de ese lado se acercan uno y los n−size[c] restantes se alejan uno. Por eso ans[c]=ans[v]+n−2·size[c]. En el camino 0–1–2–3, ans[0]=6 y size[1]=3, así que ans[1]=6+4−6=4. Luego ans[2]=4 y ans[3]=6."},
{title:"Preparar la respuesta de la primera raíz",body:"En el primer recorrido calcula size[v]=1+Σ size[hijo]. Para las distancias a sus descendientes, usa down[v]=Σ(down[hijo]+size[hijo]). El valor down de la raíz es su respuesta completa. En la segunda usa la fórmula sobre cada hijo. Para otras funciones, separa la aporte que llega del padre de las que llegan de cada hijo.\n\nPrefijos y sufijos de agregados permiten excluir un hijo en O(1) cuando no puedes deshacer una combinación directamente."},
{title:"Costo y condiciones de las distancias",body:"Para un árbol sin pesos, calcular todas las sumas de distancias requiere O(n) tiempo y O(n) memoria. Con peso w en la arista padre–hijo, el cambio es w·(n−2·size[hijo]); usa long long para sumas grandes. No cambies size al cambiar mentalmente la raíz: esos tamaños están definidos respecto a la primera raíz y la fórmula ya lo contempla.\n\nPractica una estrella de cinco vértices: el centro suma cuatro y cada hoja suma siete. Después explica cómo guardar los dos mayores aportes de hijos para calcular la distancia al vértice más lejano desde cada raíz."}
],'Si n=10 y el subárbol del hijo tiene 7 vértices, ¿cuánto cambia la suma al mover la raíz a ese hijo?',['Aumenta 4','Disminuye 4','Aumenta 7','No cambia'],1,'El cambio es n−2·size = 10−14 = −4: siete vértices se acercan y tres se alejan.'),
G('tree-euler','Aplanar árboles con un recorrido de Euler',['usaco-silver-intro-tree','usaco-gold-purs'],['Convertir subárboles en intervalos','Diferenciar tiempo de entrada y recorrido completo'],[
{title:"Escribir el árbol en orden de visita",body:"Durante un DFS, anota cada vértice al entrar; todos los descendientes de un vértice quedan juntos en esa lista. Si numeras cada vértice cuando entras por primera vez, los vértices de cualquier subárbol ocupan posiciones contiguas. Guarda tin[v] al entrar y tout[v] cuando terminas sus descendientes, usando un contador que aumenta solo al entrar. Entonces el subárbol de v corresponde al intervalo semiabierto [tin[v],tout[v])."},
{title:"Localizar un subárbol en el arreglo",body:"Con raíz cero, hijos uno y dos, e hijos tres y cuatro bajo el uno, un posible orden es [0,1,3,4,2]. Visitando primero uno, el orden de entrada es [0,1,3,4,2]. El subárbol de uno ocupa índices [1,4): contiene uno, tres y cuatro. Si sus valores son 5,2,7 respectivamente, sumar ese subárbol equivale a consultar 5+2+7=14 en el arreglo.\n\nUn cambio de valor de tres se vuelve una actualización puntual en tin[3]=2."},
{title:"Aplicar consultas al arreglo resultante",body:"Con el orden DFS puedes usar Fenwick o un árbol de segmentos para sumar subárboles y cambiar valores puntuales. También u es ancestro de v si tin[u]≤tin[v]<tout[u]. La numeración no convierte automáticamente cualquier camino entre dos vértices en un intervalo; para eso necesitas otra técnica.\n\nEl recorrido Euler completo que registra retornos al padre tiene 2n−1 apariciones y cumple otra función, como reducir LCA a una consulta de mínimo."},
{title:"El costo de numerar y consultar",body:"Numerar el árbol cuesta O(n). Después, las sumas y actualizaciones con Fenwick o árbol de segmentos cuestan O(log n) cada una y usan O(n) memoria. Mantén una convención única: intervalos semiabiertos evitan restas confusas, pero un Fenwick suele usar índices desde uno y requiere convertirlos con cuidado. Un solo vértice debe producir tin=0 y tout=1.\n\nPractica agregando un valor a todo un subárbol y consultando un vértice: usa un arreglo de diferencias sobre [tin,tout) y un Fenwick de prefijos. Explica por qué los descendientes reciben exactamente esa actualización y los demás no."}
],'Con el orden [0,1,3,4,2], ¿qué intervalo semiabierto representa el subárbol de 1?',['[1,3)','[1,4)','[0,4)','[2,5)'],1,'Los índices 1,2,3 contienen 1,3,4; la frontera exclusiva es 4.' ,true),
G('lca-euler','Ancestro común más bajo mediante Euler y RMQ',['usaco-gold-tree-euler'],['Reducir LCA a un mínimo de profundidad','Construir una tabla dispersa estática'],[
{title:"Dónde se juntan dos caminos hacia la raíz",body:"El ancestro común más bajo de u y v es el vértice compartido más profundo en sus caminos hacia la raíz. Es útil para distancias, caminos y consultas sobre relaciones familiares. Registra un recorrido Euler completo: añade un vértice al entrar y vuelve a añadir al padre después de regresar de cada hijo. Guarda la primera aparición de cada vértice y su profundidad en el árbol."},
{title:"Seguir las bajadas y los regresos",body:"Con raíz cero, hijos uno y dos, y hojas tres y cuatro bajo uno, Euler puede escribir [0,1,3,1,4,1,0,2,0]. Sus profundidades son [0,1,2,1,2,1,0,1,0]. Entre las primeras apariciones de tres y cuatro, el mínimo de profundidad corresponde a uno, así que LCA(3,4)=1. Entre tres y dos, el mínimo es cero. La DFS debe subir hasta su ancestro compartido antes de entrar al otro subárbol."},
{title:"Preparar mínimos por bloques",body:"En una tabla dispersa, st[k][i] guarda el índice de menor profundidad dentro del bloque que empieza en i y mide 2^k. Combina dos mitades para construir cada bloque. Para consultar [l,r], toma k=floor(log₂(r−l+1)) y compara los bloques que comienzan en l y terminan en r. Pueden solaparse porque mínimo es idempotente: contar un elemento dos veces no cambia el mínimo.\n\nEsta consulta de dos bloques no sirve del mismo modo para sumas."},
{title:"Costo y distancia entre vértices",body:"Euler ocupa O(n); preparar la tabla dispersa requiere O(n log n) tiempo y memoria. Con ella, cada LCA se responde en O(1). La distancia sin pesos es depth[u]+depth[v]−2·depth[LCA(u,v)]. No confundas la posición en Euler con la profundidad: un vértice puede aparecer muchas veces con la misma profundidad. Practica LCA(1,4), que debe ser uno, y LCA(v,v), que debe ser v.\n\nEn el ejemplo, la distancia entre tres y dos es 2+1−2·0=3. Si cambian las aristas del árbol, este preprocesamiento estático deja de ser válido."}
],'¿Por qué pueden solaparse los dos bloques de una consulta RMQ?',['Porque todo bloque mide uno','Porque mínimo es idempotente','Porque las profundidades son únicas'],1,'min(x,x)=x; una aparición repetida no altera el mínimo. Las profundidades no necesitan ser únicas.' ,true),
G('ternary-search','Búsqueda ternaria y funciones unimodales',['usaco-silver-binary-search'],['Reconocer una función con un solo valle','Distinguir búsqueda real y discreta'],[
{title:"Una función que baja y luego sube",body:"La búsqueda ternaria sirve para localizar un mínimo cuando la función disminuye hasta él y después aumenta. Para minimizar, compara dos puntos interiores m1 y m2 con m1<m2. Si f(m1)>f(m2), el mínimo no está estrictamente a la izquierda de m1 bajo las hipótesis de unimodalidad; si f(m1)<f(m2), descartas la parte derecha de m2.\n\nLa prueba depende de la forma de la función, no de que sus valores parezcan suaves."},
{title:"Probar dos puntos interiores",body:"Considera f(x)=(x−4)²+3 en [0,12]. El mínimo está en x=4 y vale tres, porque un cuadrado nunca es negativo.\n\nPrueba m1=4 y m2=8: dan tres y diecinueve. Como la función baja hasta un único mínimo y después sube, no necesitas conservar la parte a la derecha de m2. Repite la comparación en el intervalo reducido.\n\nLa función debe tener esa forma para justificar el descarte. Ver que funciona en este ejemplo no demuestra que sirva para una función con varios mínimos separados.\n\nEn una función estrictamente unimodal, si f(m1)=f(m2), puedes conservar [m1,m2]. Con mesetas fuera del mínimo, esa igualdad no basta: revisa qué garantía permite tu regla antes de quitar ambos extremos."},
{title:"Detener la búsqueda con la precisión necesaria",body:"Para números reales, elige suficientes iteraciones para la precisión pedida y evalúa el punto final; cada reducción del intervalo permite acotar el error en x. En un dominio entero, detente cuando queden pocas posiciones y revísalas todas, evitando que divisiones enteras dejen m1 igual a una frontera indefinidamente.\n\nPara una secuencia discretamente convexa, buscar el primer índice donde f(i+1)−f(i) no sea negativo con búsqueda binaria suele ser más sencillo."},
{title:"Contar evaluaciones de la función",body:"En reales necesitas O(log(rango/precisión)) evaluaciones y en enteros O(log n); multiplica ese número por el costo de evaluar f. Si la función tiene varios valles, como una combinación oscilatoria, puedes descartar el mínimo global sin darte cuenta. Practica minimizar max(|x−2|,|x−8|): el centro x=5 alcanza valor tres y la función es convexa.\n\nLuego compara con minimizar una función dada solo por una tabla irregular: sin demostrar su forma, la búsqueda ternaria no tiene garantía."}
],'Para f(x)=(x−4)²+3, ¿cuál es el mínimo?',['x=3, valor 4','x=4, valor 3','x=0, valor 19'],1,'Un cuadrado es no negativo y se hace cero exactamente en x=4; entonces f(4)=3.'),
G('hashing','Huellas de cadenas y colisiones',['usaco-gold-modular'],['Comparar subcadenas con hashes polinomiales','Separar probabilidad de garantía'],[
{title:"Dar una huella numérica a un texto",body:"Un hash transforma una cadena en un número pequeño que ayuda a compararla con otras rápidamente. Si dos cadenas tienen huellas diferentes, son distintas; si coinciden, podrían ser iguales o una colisión. Esta asimetría es fundamental: un hash no constituye una prueba exacta de igualdad por sí mismo.\n\nEn concursos, los hashes polinomiales permiten comparar muchas subcadenas rápidamente, pero debes elegir módulos, base y estrategia según la tolerancia a errores del problema."},
{title:"Construir la huella de cada prefijo",body:"Da un código positivo a cada letra. Empieza con H[0]=0 y calcula H[i+1]=(H[i]·B+código(s[i])) mod M. Guarda también potencias de B. La huella de s[l..r) es H[r]−H[l]·B^(r−l), normalizada módulo M. Con B=10, M=101 y códigos [1,2,3], los prefijos son 0,1,12,22. Para las dos últimas cifras, 22−1·100 ≡ 23 módulo 101, que coincide con codificar [2,3]."},
{title:"Consultar un fragmento en tiempo constante",body:"Después de preparar los prefijos y las potencias, obtienes el hash de cualquier subcadena en O(1). Puedes combinar comparaciones de prefijos con búsqueda binaria para hallar una longitud común máxima, o comparar una cadena con su reversa para buscar palíndromos. Incluye la longitud cuando el formato pueda confundir secuencias de distintos tamaños.\n\nDos módulos y una base aleatoria reducen riesgos de colisión, pero no convierten el procedimiento en determinista; si necesitas certeza, comprueba candidatos o usa algoritmos exactos."},
{title:"Costo y pruebas de la comparación",body:"Preparar los hashes requiere O(n) tiempo y O(n) memoria para una cadena de longitud n. La probabilidad de alguna colisión aumenta cuando realizas muchas comparaciones, por lo que no basta citar el tamaño de un módulo sin considerar el número de consultas. Cuida overflow en productos y normaliza las restas negativas.\n\nPractica calculando con el módulo pequeño del ejemplo una colisión deliberada: [1,0,1] codifica 101 y [0] codifica cero. Explica qué parte se arregla almacenando longitud y por qué todavía pueden existir colisiones entre cadenas de igual longitud."}
],'Si dos hashes coinciden, ¿qué puedes afirmar siempre?',['Las cadenas son iguales','Podría existir una colisión','Las cadenas tienen igual longitud'],1,'La huella tiene menos posibilidades que las cadenas posibles; diferentes cadenas pueden compartir el mismo valor.'),
G('hashmaps','Tablas hash y frecuencias de estados',['usaco-bronze-intro-sets','usaco-silver-prefix-sums'],['Contar coincidencias con unordered_map','Evaluar costo esperado y peor caso'],[
{title:"Encontrar un dato por su clave",body:"Un mapa asocia cada clave con un valor, por ejemplo una suma de prefijo con la cantidad de veces que apareció. Es útil para frecuencias, estados visitados y memorias cuando el conjunto de claves no se conoce de antemano. No mantiene el orden numérico de las claves ni permite consultar vecinos con lower_bound.\n\nEl contenedor resuelve colisiones comparando claves: una colisión puede volverlo lento, pero no hace que claves distintas sean confundidas como en una comparación manual de huellas."},
{title:"Derivar el prefijo que hace falta",body:"Llama pref[j] a la suma de los primeros j valores; así pref[0]=0 representa el tramo vacío anterior al arreglo. Un subarreglo [i,j) suma T si pref[i]=pref[j]−T. Recorre j de izquierda a derecha y guarda cuántas veces apareció cada prefijo anterior. En [1,−1,1] con T=1, los prefijos son 0,1,0,1. Al llegar a los prefijos uno, cero y uno, encuentras respectivamente 1,0 y 2 coincidencias: hay tres subarreglos.\n\nInicializar la frecuencia de cero en uno cuenta los que empiezan en la primera posición."},
{title:"Consultar antes de registrar",body:"Cuando el nuevo prefijo suma s, añade frecuencia[s−T] a la respuesta y después incrementa frecuencia[s]. Insertar primero contaría un subarreglo vacío cuando T=0. Usa long long tanto para prefijos como para el conteo, pues puede haber n(n+1)/2 subarreglos. Con operator[] una clave ausente se inserta con valor cero; para preguntas de existencia sin insertar puedes usar find. Reservar capacidad reduce redistribuciones durante un gran número de inserciones."},
{title:"Distinguir tiempo esperado y garantizado",body:"Con una tabla hash bien distribuida, la solución tarda O(n) en promedio y ocupa O(n) memoria. Con colisiones adversas, el peor caso puede llegar a O(n²). Un map ofrece O(n log n) con garantía de árbol balanceado. Si todas las claves se pueden reunir antes, comprimir coordenadas y usar un vector puede ser más predecible. Practica [0,0,0] con objetivo cero: las frecuencias sucesivas producen 1+2+3=6.\n\nExplica por qué el método sigue funcionando con negativos mientras una ventana basada únicamente en sumas crecientes no."}
],'¿Por qué se guarda inicialmente frecuencia[0]=1?',['Para contar subarreglos que comienzan al inicio','Para eliminar valores negativos','Para ordenar las claves'],0,'El prefijo vacío tiene suma cero. Cuando pref[j]=T, su coincidencia representa el subarreglo [0,j).'),
G('meet-in-the-middle','Encontrarse a mitad del camino',['usaco-bronze-complete-rec','usaco-silver-binary-search-sorted-array'],['Reducir una enumeración exponencial por mitades','Combinar resultados sin formar todos los pares'],[
{title:"Cuando cuarenta elementos ya son demasiados",body:"Enumerar todos los subconjuntos de cuarenta elementos requiere cerca de un billón de posibilidades. Sin embargo, dividir los elementos en dos mitades de veinte deja alrededor de un millón de subconjuntos por mitad. Meet in the middle genera resultados parciales y los combina con una búsqueda eficiente. La mejora solo ocurre si evitas probar todas las parejas de resultados, lo que reconstruiría el costo original."},
{title:"Separar las sumas en dos mitades",body:"Con valores [2,3,5,7] y objetivo diez, puedes dividir el arreglo en [2,3] y [5,7]. Las sumas izquierdas son [0,2,3,5] y las derechas [0,5,7,12]. Para cada suma izquierda s, busca 10−s a la derecha. Encuentras s=3 con siete y s=5 con cinco: dos subconjuntos. Debes conservar repeticiones de sumas si cuentas subconjuntos distintos, porque varias elecciones pueden producir el mismo total."},
{title:"Generar las sumas sin repetir decisiones",body:"Empieza con la suma cero. Por cada nuevo valor x, conserva las sumas anteriores y añade una copia de cada una con x agregado. Ordena las sumas derechas; equal_range permite contar todas las apariciones del complemento. El programa admite hasta cuarenta elementos y asume que las sumas caben en long long.\n\nValores negativos no rompen este método, ya que la búsqueda opera sobre la lista ordenada de sumas resultantes.",code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nvector<long long> sums(const vector<long long>&a,int l,int r){vector<long long>s{0};for(int i=l;i<r;i++){int z=s.size();for(int j=0;j<z;j++)s.push_back(s[j]+a[i]);}return s;}\nint main(){int n;long long target;cin>>n>>target;if(n<0||n>40)return 0;vector<long long>a(n);for(auto&x:a)cin>>x;auto L=sums(a,0,n/2),R=sums(a,n/2,n);sort(R.begin(),R.end());long long ans=0;for(auto x:L){auto p=equal_range(R.begin(),R.end(),target-x);ans+=p.second-p.first;}cout<<ans<<"\\n";}'},
{title:"Calcular el costo de combinar",body:"Generar mitades equilibradas cuesta O(2^(n/2)); ordenar y buscar añade un factor O(n). El total es O(n·2^(n/2)) tiempo y O(2^(n/2)) memoria. Para maximizar una suma que no exceda T, busca el mayor complemento permitido en vez de uno exacto. No elimines duplicados si representan objetos diferentes y buscas un conteo. Practica [1,1,2] con objetivo dos: hay dos subconjuntos, el objeto de valor dos y la pareja de unos.\n\nEl subconjunto vacío cuenta cuando el objetivo es cero, salvo que el enunciado lo prohíba."}
],'¿Cuántos subconjuntos de [2,3,5,7] suman diez?',['1','2','3','4'],1,'Son {3,7} y {2,3,5}; las dos elecciones aparecen al combinar complementos de las mitades.'),
G('gold-conclusion','Taller de cierre de Oro',['usaco-gold-knapsack','usaco-gold-shortest-paths','usaco-gold-purs','usaco-gold-meet-in-the-middle'],['Elegir algoritmos por estructura y límites','Preparar una solución verificable de concurso'],[
{title:"Elegir qué información guardar",body:"Antes de buscar un algoritmo, escribe qué necesitas responder y qué información puede cambiar durante el problema. Antes de buscar una etiqueta, escribe qué pide exactamente la respuesta y cuáles son las operaciones permitidas. Después identifica la parte que una solución exhaustiva repite. El algoritmo correcto suele aparecer al resumir ese trabajo repetido sin perder información necesaria para el futuro."},
{title:"Comparar problemas con límites distintos",body:"Compara cuatro tareas; sus límites nos llevarán a guardar información diferente en cada caso. Para cuarenta objetos y sumas enormes, meet in the middle puede ser viable. Para mil objetos y capacidad diez mil, una mochila O(nW) hace unos diez millones de transiciones. Para doscientos mil vértices y pesos no negativos, una lista de adyacencia con Dijkstra resulta natural.\n\nPara doscientos mil cambios y sumas en un arreglo, Fenwick evita recomputar prefijos. Los números no demuestran por sí solos la solución, pero descartan enfoques incompatibles."},
{title:"Empezar con una solución que puedas comprobar",body:"Construye primero una solución sencilla para entradas pequeñas, aunque enumere todas las posibilidades. Servirá para entender el problema y comprobar una versión más rápida. Luego expresa un invariante o recurrencia y explica qué decisiones cubre. Estima tiempo y memoria usando los límites máximos, no solo el ejemplo. Programa casos base antes de optimizaciones y compara resultados con la solución pequeña en entradas aleatorias.\n\nPara un algoritmo probabilístico como hashing, registra explícitamente esa limitación; para uno voraz, busca un argumento de intercambio que justifique cada elección."},
{title:"Revisar cómo eliges una herramienta",body:"Resuelve un problema de DP, otro de grafos y otro de consultas sin mirar antes sus etiquetas. En cada uno, explica qué información decidiste guardar. Al terminar, redacta qué falló, qué caso lo detectó y por qué la corrección funciona. Como mini examen, decide si BFS resuelve aristas de pesos uno y siete: no, porque las capas cuentan aristas y no costo.\n\nDespués explica por qué una tabla de mochila con W=10⁹ es inviable aunque n=100. Puedes avanzar a Platino cuando seas capaz de formular y defender una solución nueva con estas herramientas, no solo reproducir una plantilla conocida."}
],'Con 40 objetos y pesos hasta 10⁹, ¿qué técnica merece explorar para suma de subconjuntos?',['DP por capacidad hasta 4·10¹⁰','Meet in the middle','Ordenar y tomar siempre el menor'],1,'Dos mitades de veinte generan cerca de 2²⁰ sumas cada una, mientras una tabla por capacidad sería demasiado grande.'),
];
